/**
 * Единый API виджета визуализации.
 *
 * Потребитель всегда передаёт данные в одном формате (`VisualizationWidgetData`),
 * а виджет сам маппит их на нужный движок:
 *  - `sales`      → `@gravity-ui/charts` (плагин ChartKit `gravity-charts`) — обычный линейный график;
 *  - `monitoring` → `@gravity-ui/yagr`   (плагин ChartKit `yagr`)           — плотный временной ряд.
 *
 * Оба движка загружаются лениво самим ChartKit (`React.lazy` внутри плагинов).
 */

export type VisualizationMode = 'sales' | 'monitoring';

export interface VisualizationSeries {
    /** Стабильный идентификатор серии (используется в легенде и тултипе). */
    id: string;
    /** Отображаемое имя серии. */
    name: string;
    /** Значения по оси Y. Длина массива должна совпадать с `VisualizationWidgetData.timestamps`. */
    values: Array<number | null>;
    /** Цвет серии. Если не указан — берётся из палитры движка. */
    color?: string;
}

export interface VisualizationWidgetData {
    /** Метки времени (мс, Unix epoch), общая ось X для всех серий. */
    timestamps: number[];
    series: VisualizationSeries[];
    /** Подпись оси Y (например, «₽» или «req/s»). */
    valueLabel?: string;
    /** Единицы измерения, добавляются к значениям в тултипе. */
    unit?: string;
    /** Таймзона для оси X и тултипа (например, `Europe/Moscow`). */
    timeZone?: string;
}

export interface VisualizationWidgetProps {
    /** Заголовок виджета. */
    title: string;
    /** Текущий режим. Если не передан, виджет управляет режимом сам (uncontrolled). */
    mode?: VisualizationMode;
    /** Режим по умолчанию для uncontrolled-варианта. */
    defaultMode?: VisualizationMode;
    /** Колбэк смены режима. */
    onModeChange?: (mode: VisualizationMode) => void;
    /** Данные для режима «продажи». */
    salesData: VisualizationWidgetData;
    /** Данные для режима «мониторинг». */
    monitoringData: VisualizationWidgetData;
    /** Высота области графика в пикселях. */
    height?: number;
    className?: string;
}
EOF
cat > src/widgets/VisualizationWidget/registerPlugins.ts <<'EOF'
import {settings} from '@gravity-ui/chartkit';
import {GravityChartsPlugin} from '@gravity-ui/chartkit/gravity-charts';
import {YagrPlugin} from '@gravity-ui/chartkit/yagr';

let registered = false;

/**
 * Регистрирует оба плагина ChartKit. Вызывается один раз на входе в приложение.
 *
 * Регистрация плагина — это только запись в реестр: сам рендерер плагина обёрнут в `React.lazy`,
 * поэтому код `@gravity-ui/charts` и `@gravity-ui/yagr` подтягивается отдельными чанками
 * лишь при первом рендере `<ChartKit type="gravity-charts" />` / `<ChartKit type="yagr" />`.
 */
export function registerVisualizationPlugins(): void {
    if (registered) {
        return;
    }
    registered = true;
    settings.set({plugins: [GravityChartsPlugin, YagrPlugin]});
}
EOF
cat > src/widgets/VisualizationWidget/adapters/toGravityCharts.ts <<'EOF'
import type {ChartData, LineSeries, LineSeriesData} from '@gravity-ui/chartkit/gravity-charts';

import type {VisualizationWidgetData} from '../types';

/**
 * Маппит единые данные виджета на конфиг `@gravity-ui/charts` (плагин `gravity-charts`):
 * обычный линейный график с datetime-осью X.
 */
export function toGravityChartsData(input: VisualizationWidgetData): ChartData {
    const series: LineSeries[] = input.series.map((serie) => {
        const data: LineSeriesData[] = [];

        input.timestamps.forEach((x, index) => {
            const y = serie.values[index];
            if (y !== null && y !== undefined) {
                data.push({x, y});
            }
        });

        return {
            type: 'line',
            id: serie.id,
            name: serie.name,
            color: serie.color,
            data,
            marker: {enabled: true},
        };
    });

    return {
        series: {data},
        xAxis: {
            type: 'datetime',
            grid: {enabled: false},
        },
        yAxis: [
            {
                type: 'linear',
                min: 0,
                title: input.valueLabel ? {text: input.valueLabel} : undefined,
                labels: {
                    numberFormat: input.unit ? {postfix: ` ${input.unit}`} : undefined,
                },
            },
        ],
        legend: {enabled: true},
        tooltip: {enabled: true},
    };

    function data(): never {
        throw new Error('unreachable');
    }
}
EOF
