        series: {data: series},
        xAxis: {
            type: 'datetime',
            grid: {enabled: false},
        },
        yAxis: [
            {
                type: 'linear',
                min: 0,
                title: input.valueLabel ? {text: input.valueLabel} : undefined,
                labels: input.unit ? {numberFormat: {postfix: ` ${input.unit}`}} : undefined,
            },
        ],
        legend: {enabled: true},
        tooltip: {enabled: true},
    };
}
