/** Детерминированный псевдослучайный генератор, чтобы демо-данные были стабильны между рендерами. */
function createRandom(seed: number) {
    let state = seed;
    return () => {
        state = (state * 1664525 + 1013904223) % 4294967296;
        return state / 4294967296;
    };
}

